import { Injectable } from '@angular/core';
import { SecureStorageService } from '../../../core/services/storage/secure-storage.service';
import { environment } from '../../../../environments/environment';
import { firstValueFrom } from 'rxjs';
import { HttpClient } from '@angular/common/http';
import { TostbarService } from '../../../core/services/tost/tostbar.service';
import { DownloadService } from '../../../userpanel/services/download/download.service';

@Injectable({
  providedIn: 'root'
})
export class HyperlinkService {

  url: string = `${environment.downloadapiservice}`;
  constructor(private http: HttpClient, private tost: TostbarService, private sStore: SecureStorageService,
    private downloadService: DownloadService
  ) { }

  async downloadFiles(mdl: { nCaseid: string, nSectionid: string, jFolders: string, jFiles: string }): Promise<any> {
    // try {
    //   mdl['isHyperlink'] = true; // Set the flag to indicate this is a hyperlink download
    //   const res: any = await firstValueFrom(
    //     this.http.post<{ nDPid: string, msg: number, value: string }>(`${this.url}/startdownload`, mdl)
    //   );
    //   if (res && res.msg == 1) {
    //     this.tost.openSnackBar(res.value, '');
    //     return res;
    //   } else {
    //     this.tost.openSnackBar(res.value, 'E');
    //     return res;
    //   }
    // } catch (err) {
    //   this.tost.error(err["error"]?.message || 'Error downloading files');
    //   return { nDPid: '', msg: 0, value: 'Error creating bundle' };
    // }

    let nUserid = await this.sStore.getUserId();
    const sizeDetail: { msg: 1 | -1, cFinalSize: number, isValidForStream: boolean } = await this.downloadService.getApproximateUrl({ nCaseid: mdl.nCaseid, nSectionid: mdl.nSectionid, jFiles: mdl.jFiles, jFolders: mdl.jFolders, nMasterid: nUserid, isHyperlink: true });

    if (sizeDetail.isValidForStream || environment.name == 'localdocker') {
      var link = document.createElement('a');
      link.href = `${environment.downloadservice}/download/hyperlink/downloadfile?nCaseid=${mdl.nCaseid}&nSectionid=${mdl.nSectionid}&jFiles=${mdl.jFiles}&jFolders=${mdl.jFolders}&nMasterid=${nUserid}`;
      link.setAttribute('download', ('folder'));

      link.addEventListener('load', function () {
        // t.isDownLoading = false;
        console.log('Download started');
      });

      // Add an event listener to handle errors and hide the loading indicator
      link.addEventListener('error', function () {
        // t.isDownLoading = false;
        console.error('Error downloading file');
      });
      link.addEventListener('click', function () {
        // t.isDownLoading = false;
        console.log('Download link clicked');
      });

      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } else {
      // const res = await this.downloadService.downloadFiles({ nCaseid: mdl.nCaseid, nSectionid: mdl.nSectionid, jFiles: mdl.jFiles, jFolders: mdl.jFolders, isHyperlink: true });
      const res = await this.downloadBatchFiles({ nCaseid: mdl.nCaseid, nSectionid: mdl.nSectionid, jFolders: mdl.jFolders, jFiles: mdl.jFiles, isHyperlink: true });
      return (res?.msg == 1) ? 2 : 0;
    }


  }


  async downloadBatchFiles(mdl: { nCaseid: string, nSectionid: string, jFolders: string, jFiles: string, isHyperlink: boolean }): Promise<{ nDPid: string, msg: number, value: string }> {
    debugger;
    try {
      const res: any = await firstValueFrom(
        this.http.post<{ nDPid: string, msg: number, value: string }>(`${this.url}/startdownloadhyperlink`, mdl)
      );
      if (res && res.msg == 1) {
        this.tost.openSnackBar(res.value, '');
        return res;
      } else {
        this.tost.openSnackBar(res.value, 'E');
        return res;
      }
    } catch (err) {
      this.tost.error(err["error"]?.message || 'Error downloading files');
      return { nDPid: '', msg: 0, value: 'Error download file' };
    }
  }
}
